/*
 * node_modules/express — minimal Express-shaped router for the SEVM stack.
 *
 * This is a compatibility *target*, not a reimplementation of the full npm
 * package: it exposes the subset the SEVM demo needs (get/post routing,
 * res.json / res.end / res.status) so that application code written against
 * Express keeps working. It deliberately skips the Express features that
 * would need Node internals we do not provide yet (middleware chains, body
 * parsing, template engines, virtual hosts).
 */

import { createServer } from '../net/index.js';

export function express() {
    const routes = [];

    function app(req, res) {
        const target = req.path || req.url;
        for (const r of routes) {
            if (r.method === req.method && r.path === target)
                return r.fn(req, res);
        }
        res.status(404).json({ error: 'Not Found', path: target });
    }

    app.get = (path, fn) => { routes.push({ method: 'GET', path, fn }); return app; };
    app.post = (path, fn) => { routes.push({ method: 'POST', path, fn }); return app; };
    app.put = (path, fn) => { routes.push({ method: 'PUT', path, fn }); return app; };
    app.del = (path, fn) => { routes.push({ method: 'DELETE', path, fn }); return app; };

    app.listen = (port, onListen) => {
        const server = createServer(app);
        return server.listen(port, onListen);
    };

    return app;
}

export default express;
